def comb_sort(arr):
    gap = len(arr)
    shrink_factor = 1.3
    swapped = True

    while gap > 0:
        new_gap = int(gap / shrink_factor)
        if new_gap == 0 and not swapped:
            break

        gap = new_gap or 1
        swapped = False

        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

    return arr

